                nivel.creditoProximaCompra(subtotalProdutos),
                nivel.temBrinde(subtotalProdutos));
    }

    private Cupom cupomDe(Solicitacao solicitacao) {
        String codigo = solicitacao.cupom();
        if (codigo == null || codigo.isBlank()) {
