    @Test
    void exemplo1_expressa_bemvindo10_pix_bronze_norte() {
        Resumo resumo = calculadora.calcular(new Solicitacao(
                List.of(CAMISETA, TENIS), "EXPRESSA", "BEMVINDO10", "PIX", 1, "BRONZE", "NORTE"));

        assertThat(resumo).isEqualTo(new Resumo(
