1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.dominio.clube.NivelClube;
4	import com.loja.checkout.dominio.clube.Niveis;
5	import com.loja.checkout.dominio.cupom.Cupom;
6	import com.loja.checkout.dominio.cupom.Cupons;
7	import com.loja.checkout.dominio.entrega.Entregas;
8	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
9	import com.loja.checkout.dominio.pagamento.Cobranca;
10	import com.loja.checkout.dominio.pagamento.FormaPagamento;
11	import com.loja.checkout.dominio.pagamento.Pagamentos;
12	import org.springframework.stereotype.Service;
13	
14	import java.math.BigDecimal;
15	
16	/**
17	 * A ordem do cálculo e a ordem da conferência dos erros: é o que não muda de
18	 * caso para caso. O que muda está nas implementações de cada eixo.
19	 */
20	@Service
21	public class CalculadoraResumo {
22	
23	    public Resumo calcular(Solicitacao solicitacao) {
24	        Pedido pedido = Carrinho.validar(solicitacao.itens());
25	        NivelClube nivel = Niveis.CATALOGO.exigir(solicitacao.nivelClube());
26	        Regiao regiao = Regiao.CATALOGO.exigir(solicitacao.regiao());
27	
28	        ModalidadeEntrega entrega = Entregas.CATALOGO.exigir(solicitacao.modalidadeEntrega());
29	        if (!entrega.atende(pedido)) {
30	            throw new ErroPedido("MODALIDADE_INDISPONIVEL");
31	        }
32	
33	        Cupom cupom = cupomDe(solicitacao);
34	        if (cupom != null && !cupom.aplicavelA(pedido)) {
35	            throw new ErroPedido("CUPOM_NAO_APLICAVEL");
36	        }
37	
38	        FormaPagamento pagamento = Pagamentos.CATALOGO.exigir(solicitacao.formaPagamento());
39	        int parcelas = solicitacao.parcelas() == null ? 1 : solicitacao.parcelas();
40	        if (!pagamento.aceitaParcelas(parcelas)) {
41	            throw new ErroPedido("PARCELAMENTO_INVALIDO");
42	        }
43	
44	        BigDecimal subtotalProdutos = pedido.subtotalProdutos();
45	        BigDecimal frete = nivel.isentaFrete() ? Dinheiro.ZERO : entrega.frete(pedido);
46	        BigDecimal descontoCupom = cupom == null ? Dinheiro.ZERO : cupom.desconto(pedido, frete);
47	        BigDecimal seguro = regiao.seguro(subtotalProdutos);
48	        BigDecimal totalPedido = subtotalProdutos.subtract(descontoCupom).add(frete).add(seguro);
49	
50	        if (!pagamento.atende(totalPedido)) {
51	            throw new ErroPedido("FORMA_PAGAMENTO_INDISPONIVEL");
52	        }
53	        Cobranca cobranca = pagamento.cobrar(totalPedido, parcelas);
54	
55	        return new Resumo(
56	                subtotalProdutos,
57	                descontoCupom,
58	                frete,
59	                entrega.prazoDias(),
60	                seguro,
61	                Dinheiro.centavos(cobranca.totalFinal().subtract(totalPedido)),
62	                Dinheiro.centavos(cobranca.totalFinal()),
63	                parcelas,
64	                Dinheiro.centavos(cobranca.valorParcela()),
65	                nivel.creditoProximaCompra(subtotalProdutos),
66	                nivel.temBrinde(subtotalProdutos));
67	    }
68	
69	    private Cupom cupomDe(Solicitacao solicitacao) {
70	        String codigo = solicitacao.cupom();
71	        if (codigo == null || codigo.isBlank()) {
72	            return null;
73	        }
74	        return Cupons.CATALOGO.exigir(codigo);
75	    }
76	}
