1	package com.loja.checkout.dominio;
2	
3	import com.loja.checkout.dominio.Solicitacao.ItemInformado;
4	
5	import java.math.BigDecimal;
6	import java.util.List;
7	
8	/** Transforma os itens informados pelo site num pedido, ou recusa a compra. */
9	public final class Carrinho {
10	
11	    private Carrinho() {
12	    }
13	
14	    public static Pedido validar(List<ItemInformado> informados) {
15	        if (informados == null || informados.isEmpty()) {
16	            throw new ErroPedido("PEDIDO_INVALIDO");
17	        }
18	        return new Pedido(informados.stream().map(Carrinho::item).toList());
19	    }
20	
21	    private static Item item(ItemInformado informado) {
22	        if (informado == null
23	                || !positivo(informado.precoUnitario())
24	                || !positivo(informado.quantidade())
25	                || !positivo(informado.pesoKg())) {
26	            throw new ErroPedido("PEDIDO_INVALIDO");
27	        }
28	        return new Item(
29	                informado.nome(),
30	                informado.precoUnitario(),
31	                informado.quantidade(),
32	                informado.pesoKg());
33	    }
34	
35	    private static boolean positivo(BigDecimal valor) {
36	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
37	    }
38	
39	    private static boolean positivo(Integer valor) {
40	        return valor != null && valor > 0;
41	    }
42	}
