1	package com.loja.checkout.dominio;
2	
3	import java.util.LinkedHashMap;
4	import java.util.Map;
5	
6	/**
7	 * Resolve um código vindo do pedido na implementação do caso. Escolher o caso é
8	 * uma busca no mapa, não uma cadeia de condições; código ausente ou desconhecido
9	 * vira o erro do eixo.
10	 */
11	public final class Catalogo<T> {
12	
13	    private final Map<String, T> porCodigo;
14	    private final String erroCodigoInvalido;
15	
16	    public Catalogo(Map<String, T> porCodigo, String erroCodigoInvalido) {
17	        this.porCodigo = new LinkedHashMap<>(porCodigo);
18	        this.erroCodigoInvalido = erroCodigoInvalido;
19	    }
20	
21	    public T exigir(String codigo) {
22	        T encontrado = codigo == null ? null : porCodigo.get(codigo);
23	        if (encontrado == null) {
24	            throw new ErroPedido(erroCodigoInvalido);
25	        }
26	        return encontrado;
27	    }
28	}
