26	        this.aliquotaSeguro = new BigDecimal(aliquotaSeguro);
27	    }
28	
29	    public BigDecimal seguro(BigDecimal subtotalProdutos) {
30	        return Dinheiro.percentual(subtotalProdutos, aliquotaSeguro);
31	    }
32	}
