1	package com.loja.checkout.dominio.pagamento;
2	
3	import com.loja.checkout.dominio.Dinheiro;
4	
5	import java.math.BigDecimal;
6	import java.math.MathContext;
7	
8	/** Até 3x sem juros; de 4x a 12x com juros de 1,99% ao mês (tabela Price). */
9	public final class Cartao implements FormaPagamento {
10	
11	    private static final int MAXIMO_SEM_JUROS = 3;
12	    private static final int MAXIMO_PARCELAS = 12;
13	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
14	    private static final MathContext PRECISAO = MathContext.DECIMAL128;
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean aceitaParcelas(int parcelas) {
23	        return parcelas >= 1 && parcelas <= MAXIMO_PARCELAS;
24	    }
25	
26	    @Override
27	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
28	        if (parcelas <= MAXIMO_SEM_JUROS) {
29	            return semJuros(totalPedido, parcelas);
30	        }
31	        return comJuros(totalPedido, parcelas);
32	    }
33	
34	    private Cobranca semJuros(BigDecimal totalPedido, int parcelas) {
35	        BigDecimal parcela = Dinheiro.centavos(
36	                totalPedido.divide(BigDecimal.valueOf(parcelas), PRECISAO));
37	        return new Cobranca(totalPedido, parcela);
38	    }
39	
40	    /** parcela = total x taxa / (1 - (1 + taxa)^-parcelas) */
41	    private Cobranca comJuros(BigDecimal totalPedido, int parcelas) {
42	        BigDecimal um = BigDecimal.ONE;
43	        BigDecimal fatorFinal = um.divide(um.add(TAXA_MENSAL).pow(parcelas, PRECISAO), PRECISAO);
44	        BigDecimal parcela = Dinheiro.centavos(
45	                totalPedido.multiply(TAXA_MENSAL).divide(um.subtract(fatorFinal), PRECISAO));
46	        return new Cobranca(parcela.multiply(BigDecimal.valueOf(parcelas)), parcela);
47	    }
48	}
